public class RoundedCardPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int width, int height, int arc, int inset) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            RoundedCardPainter.paint(g, width, height, arc, inset);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(80, 60, 30, 6);
            java.awt.image.BufferedImage b = render(60, 60, 0, 10);
            check("top border of the frame (40,2)", "#0000FF", pixel(a, 40, 2));
            check("left border of the frame (2,30)", "#0000FF", pixel(a, 2, 30));
            check("right border of the frame (77,30)", "#0000FF", pixel(a, 77, 30));
            check("bottom border of the frame (40,57)", "#0000FF", pixel(a, 40, 57));
            check("hollow interior (40,30)", "#FFFFFF", pixel(a, 40, 30));
            check("rounded corner leaves (1,1) white", "#FFFFFF", pixel(a, 1, 1));
            check("arc 0 gives a square corner (1,1)", "#0000FF", pixel(b, 1, 1));
            check("arc 0 interior still hollow (30,30)", "#FFFFFF", pixel(b, 30, 30));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

